def semver_sort(versions):
    def parse_version(version):
        # Split on '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split on '-' to separate core version and pre-release
        if '-' in version_without_build:
            core_part, prerelease_part = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, core_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If both have no pre-release, they're equal (will maintain order)
        if pre1 is None and pre2 is None:
            return 0
        # Version without pre-release sorts after version with pre-release
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric - compare numerically
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return cmp
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric - compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sort first
        return len(pre1) - len(pre2)

    def sort_key(version):
        major, minor, patch, prerelease = parse_version(version)

        # Create a tuple for sorting
        # For pre-release comparison: we need a tuple that sorts correctly
        # If no pre-release: sort after any pre-release (use max value)
        if prerelease is None:
            prerelease_key = (1,)  # Sorts after (0, ...)
        else:
            # Create a comparable key for pre-release identifiers
            prerelease_key = (0,) + tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in prerelease
            )

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

